"""Tests for Workspace python source file discovery and filtering."""

from __future__ import annotations

from pathlib import Path

import pytest

from depcycle.parsing.workspace import Workspace


def test_workspace_init_validation(tmp_path: Path) -> None:
    """Test validation checks on Workspace root path initialization."""
    non_existent = tmp_path / "does_not_exist"
    with pytest.raises(ValueError, match="Workspace path does not exist"):
        Workspace(non_existent)

    file_path = tmp_path / "file.txt"
    file_path.write_text("test", encoding="utf-8")
    with pytest.raises(ValueError, match="Workspace path is not a directory"):
        Workspace(file_path)


def test_workspace_should_exclude_external_path(tmp_path: Path) -> None:
    """Test _should_exclude returns True for paths outside workspace root."""
    ws_dir = tmp_path / "workspace"
    ws_dir.mkdir()
    ws = Workspace(ws_dir)

    outside_file = tmp_path / "outside.py"
    assert ws._should_exclude(outside_file, []) is True


def test_workspace_get_python_files_filtering(tmp_path: Path) -> None:
    """Test discovery and glob exclusion filtering of Python source files."""
    ws = Workspace(tmp_path)

    # Create directory structure and files
    src_dir = tmp_path / "src"
    tests_dir = tmp_path / "tests"
    venv_dir = tmp_path / ".venv"

    src_dir.mkdir()
    tests_dir.mkdir()
    venv_dir.mkdir()

    main_py = src_dir / "main.py"
    util_py = src_dir / "util.py"
    test_py = tests_dir / "test_main.py"
    venv_py = venv_dir / "lib.py"

    for path in (main_py, util_py, test_py, venv_py):
        path.write_text("# python file", encoding="utf-8")

    # Discover without exclusions
    all_files = ws.get_python_files()
    assert all_files == sorted([main_py, util_py, test_py, venv_py])

    # Discover with pattern exclusions
    filtered = ws.get_python_files(exclude_patterns=[".venv", "test_*.py"])
    assert filtered == sorted([main_py, util_py])


def test_workspace_relative_path_glob_matching(tmp_path: Path) -> None:
    ws = Workspace(tmp_path)
    sub = tmp_path / "foo" / "bar"
    sub.mkdir(parents=True)
    target = sub / "baz.py"
    target.write_text("# code", encoding="utf-8")

    # Pattern matches relative path 'foo/bar/baz.py'
    files = ws.get_python_files(exclude_patterns=["foo/bar/*.py"])
    assert files == []

